static void LogPDPImage(const PDBImage *image)
{
  static const char *type_string;
  switch(image->type)
    {
    case 0: type_string = "2 bit gray"; break;
    case 2: type_string = "4 bit gray"; break;
    default: type_string = "monochrome"; break;
    }

  (void) LogMagickEvent(CoderEvent,GetMagickModule(),
                        "PDP Image:\n"
                        "    name:       %.32s\n"
                        "    version:    %d\n"
                        "    type:       %d (%s)\n"
                        "    reserved_1: %lu\n"
                        "    note:       %lu\n"
                        "    x_last:     %u\n"
                        "    y_last:     %u\n"
                        "    reserved_2: %lu\n"
                        "    x_anchor:   %u\n"
                        "    y_anchor:   %u\n"
                        "    width:      %u\n"
                        "    height:     %u",
                        image->name,
                        image->version,
                        image->type, type_string,
                        image->reserved_1,
                        image->note,
                        image->x_last,
                        image->y_last,
                        image->reserved_2,
                        image->x_anchor,
                        image->y_anchor,
                        image->width,
                        image->height
                        );
}


/*
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%                                                                             %
%                                                                             %
%                                                                             %
%   D e c o d e I m a g e                                                     %
%                                                                             %
%                                                                             %
%                                                                             %
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
%  Method DecodeImage unpacks the packed image pixels into runlength-encoded
%  pixel packets.
%
%  The format of the DecodeImage method is:
%
%      unsigned int DecodeImage(Image *image,unsigned char *pixels,
%        const size_t length)
%
%  A description of each parameter follows:
%
%    o status:  Method DecodeImage returns True if all the pixels are
%      uncompressed without error, otherwise False.
%
%    o image: The address of a structure of type Image.
%
%    o pixels:  The address of a byte (8 bits) array of pixel data created by
%      the decoding process.
%
%
*/
static MagickPassFail DecodeImage(Image *image,unsigned char *pixels,
  const size_t length)
{
  int
    c,
    count,
    pixel;

  register long
    i;

  register unsigned char
    *p;

  MagickPassFail
    status = MagickPass;

  p=pixels;
  while (p < (pixels+length))
  {
    if ((pixel=ReadBlobByte(image)) == EOF)
      {
        status = MagickFail;
        goto decode_image_quit;
      }
    if (pixel <= 0x80)
      {
        count=pixel+1;
        for (i=0; i < count; i++)
          {
            if ((c = ReadBlobByte(image)) == EOF)
              {
                status = MagickFail;
                goto decode_image_quit;
              }
            *p++ = (unsigned char) c;
          }
        continue;
      }
    count=pixel+1-0x80;
    if ((pixel=ReadBlobByte(image)) == EOF)
      {
        status = MagickFail;
        goto decode_image_quit;
      }
